window.kbPageData["views/entry/k-f7a679076bc3fb51"] = {"key":"entry/k-f7a679076bc3fb51","state":{"route":"entry/k-f7a679076bc3fb51"},"node":{"id":"k-f7a679076bc3fb51","mode":"k","title":"实心方阵","type":"概念与词义","domain":"数学","reading":"","intro":"","priority":100,"aliases":["方阵的排数与每排人数相等"],"qs":["江苏 2024 B类 行测#63"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"实心方阵是排数与列数相等、每个位置都有人或物的正方形排列。有 n 排时，每排有 n 个成员。","review":{"definition":"实心方阵是排数与列数相等、每个位置都有人或物的正方形排列。有 n 排时，每排有 n 个成员。","explanation":"本题按排划分研究生和本科生。设本科生有 x 排，研究生有 3 排，则方阵每排有 x + 3 人。本科生人数满足 x(x + 3) = 270，由 15 × 18 = 270 得每排 18 人，因此研究生有 3 × 18 = 54 人。","references":[],"evidence":"方阵为（x+3）排、（x+3）列","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 B类 行测#63":{"paper":"江苏 2024 B类 行测","n":63,"mod":"数量关系","src":["0ae7ac475476e5635bd7.pdf",10],"asrc":["8dd171daee6fc74e9718.pdf",19],"card":"dffa76d68f33153805dcf2fa","links":[{"id":"k-f7a679076bc3fb51","role":"解题依据","why":"总排数等于每排人数，据此可将两类学生的人数都表示为各自的排数乘以每排人数。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-f7a679076bc3fb51":[["江苏 2024 B类 行测#63"]]}};
